"""Linux-only controlled delay experiment; no application source modification."""
import subprocess
import sys
import pytest

@pytest.fixture(autouse=True)
def delay_actual_children(request, monkeypatch):
    if request.node.name != 'test_separate_cli_process_asks_while_ingestion_and_summaries_continue':
        return
    original = subprocess.Popen
    def delayed_popen(args, *positional, **kwargs):
        delay = 13 if any(str(arg).endswith('capture.py') for arg in args) else 21
        # exec preserves the process identity and executes the original Python CLI arguments.
        code = 'import os,sys,time;time.sleep(float(sys.argv[1]));os.execv(sys.executable,[sys.executable]+sys.argv[2:])'
        return original([sys.executable, '-c', code, str(delay), *args[1:]], *positional, **kwargs)
    monkeypatch.setattr(subprocess, 'Popen', delayed_popen)
